import { NextRequest } from "next/server";
import { z } from "zod";
import { ingestTicker } from "@/lib/ingest";

export const dynamic = "force-dynamic";
export const maxDuration = 300;

const Body = z.object({
  ticker: z.string().min(1).max(12),
  resolution: z.enum(["daily", "weekly", "monthly"]).optional(),
  /** Rebuild the SEC side without touching stored prices. */
  skipPrices: z.boolean().optional(),
  /**
   * CIK for companies SEC's ticker directory cannot resolve. Delisted filers are
   * dropped from it — Rowan Companies (RDC, CIK 0000085408) has ten years of
   * 10-K in EDGAR and no directory entry — so without this the only companies
   * reachable are the ones still trading.
   */
  cik: z
    .string()
    .trim()
    .regex(/^\d{1,10}$/, "CIK je 1–10 číslic")
    .transform((c) => c.padStart(10, "0"))
    .nullish(),
});

/** Streams newline-delimited JSON progress events while the ingest runs. */
export async function POST(req: NextRequest) {
  let ticker: string;
  let resolution: "daily" | "weekly" | "monthly" | undefined;
  let skipPrices = false;
  let cik: string | null = null;
  try {
    const parsed = Body.parse(await req.json());
    ticker = parsed.ticker;
    resolution = parsed.resolution;
    skipPrices = parsed.skipPrices ?? false;
    cik = parsed.cik ?? null;
  } catch {
    return Response.json({ error: "Očekávám { ticker: string }" }, { status: 400 });
  }

  const encoder = new TextEncoder();
  const stream = new ReadableStream({
    async start(controller) {
      const send = (obj: unknown) =>
        controller.enqueue(encoder.encode(JSON.stringify(obj) + "\n"));
      try {
        for await (const progress of ingestTicker(ticker, resolution, cik, skipPrices)) {
          send(progress);
        }
      } catch (e) {
        send({
          step: "error",
          message: "Ingest selhal",
          pct: 100,
          done: true,
          error: (e as Error).message,
        });
      } finally {
        controller.close();
      }
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "application/x-ndjson; charset=utf-8",
      "Cache-Control": "no-store, no-transform",
    },
  });
}
